    data = json.load(f)
def walk(node, out):
    if isinstance(node, dict):
        if node.get('type') == 'text' and 'text' in node:
            out.append(node['text'])
        for v in node.values():
            walk(v, out)
    elif isinstance(node, list):
        for v in node:
            walk(v, out)
out = []
walk(data.get('primaryContentSections'), out)
text = ' '.join(out)
print(text[:6000])
